// Generated from the Concurrency Auditor dashboard design. Placeholders:
// __FINDINGS__ (JSON), __SUB__, __SCORE__, __OFFSET__, __META__ (HTML).
export const TEMPLATE: string = "<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Concurrency Auditor</title>
<style>
:root{
  --bg:#f6f7f9; --surface:#ffffff; --surface-2:#f0f2f5; --border:#e2e5ea;
  --text:#14171c; --muted:#5f6773; --accent:#5b5bd6;
  --crit:#d92d20; --crit-bg:#fdecea; --high:#e8590c; --high-bg:#fff1e6;
  --med:#b7791f; --med-bg:#fdf6e3; --low:#3b82f6; --low-bg:#e8f0fe;
  --ok:#16a34a; --code-bg:#0f1218; --code-text:#e6e8ec;
  --kw:#ff7ab2; --ty:#5dd8ff; --str:#fc6a5d; --cm:#7f8c98; --at:#d0a8ff;
}
@media (prefers-color-scheme: dark){
  :root:not([data-theme="light"]){
    --bg:#0d0f13; --surface:#161a20; --surface-2:#1d222a; --border:#2a303a;
    --text:#e8eaee; --muted:#9aa3ae; --accent:#8b8bff;
    --crit-bg:#3a1714; --high-bg:#3a2010; --med-bg:#33290f; --low-bg:#14233d;
    --code-bg:#0a0c10;
  }
}
:root[data-theme="dark"]{
  --bg:#0d0f13; --surface:#161a20; --surface-2:#1d222a; --border:#2a303a;
  --text:#e8eaee; --muted:#9aa3ae; --accent:#8b8bff;
  --crit-bg:#3a1714; --high-bg:#3a2010; --med-bg:#33290f; --low-bg:#14233d;
  --code-bg:#0a0c10;
}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--text);
  font:15px/1.5 -apple-system,BlinkMacSystemFont,"SF Pro Text","Segoe UI",Roboto,sans-serif}
.wrap{max-width:960px;margin:0 auto;padding:20px 16px 60px}
header{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:18px}
.logo{width:40px;height:40px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#c056e8);
  display:grid;place-items:center;color:#fff;font-weight:700;font-size:18px;flex:none}
header h1{font-size:20px;margin:0;line-height:1.2}
header .sub{color:var(--muted);font-size:13px}
header .actions{margin-left:auto;display:flex;gap:8px}
button{font:inherit;cursor:pointer;border-radius:8px;border:1px solid var(--border);
  background:var(--surface);color:var(--text);padding:7px 12px;font-size:13px}
button.primary{background:var(--accent);border-color:var(--accent);color:#fff}
button:hover{filter:brightness(.97)}

.summary{display:grid;grid-template-columns:200px 1fr;gap:14px;margin-bottom:18px}
.card{background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:16px}
.score{display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}
.ring{position:relative;width:110px;height:110px}
.ring svg{transform:rotate(-90deg)}
.ring .val{position:absolute;inset:0;display:grid;place-items:center;font-size:26px;font-weight:700}
.score .lbl{margin-top:8px;font-size:13px;color:var(--muted)}
.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
.stat{border-radius:10px;padding:12px;background:var(--surface-2)}
.stat .n{font-size:24px;font-weight:700;line-height:1.1}
.stat .t{font-size:12px;color:var(--muted)}
.stat.crit .n{color:var(--crit)} .stat.high .n{color:var(--high)}
.stat.med .n{color:var(--med)} .stat.low .n{color:var(--low)}
.meta{display:flex;gap:16px;flex-wrap:wrap;margin-top:12px;font-size:13px;color:var(--muted)}
.meta b{color:var(--text);font-weight:600}

.toolbar{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:12px}
.chip{border-radius:999px;padding:6px 12px;font-size:13px}
.chip.on{background:var(--text);color:var(--bg);border-color:var(--text)}
.search{flex:1;min-width:160px;padding:8px 12px;border-radius:8px;border:1px solid var(--border);
  background:var(--surface);color:var(--text);font:inherit;font-size:14px}

.finding{background:var(--surface);border:1px solid var(--border);border-radius:12px;margin-bottom:10px;overflow:hidden}
.fhead{display:flex;gap:12px;align-items:flex-start;padding:14px;cursor:pointer}
.sev{flex:none;font-size:11px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;
  padding:3px 8px;border-radius:6px;margin-top:2px}
.sev.critical{color:var(--crit);background:var(--crit-bg)}
.sev.high{color:var(--high);background:var(--high-bg)}
.sev.medium{color:var(--med);background:var(--med-bg)}
.sev.low{color:var(--low);background:var(--low-bg)}
.ftitle{font-weight:600}
.floc{font:12px/1.4 ui-monospace,"SF Mono",Menlo,monospace;color:var(--muted);margin-top:2px;word-break:break-all}
.rule{font:11px ui-monospace,"SF Mono",Menlo,monospace;color:var(--muted);border:1px solid var(--border);
  border-radius:5px;padding:1px 6px;margin-left:6px}
.chev{margin-left:auto;color:var(--muted);transition:transform .2s;flex:none}
.finding.open .chev{transform:rotate(90deg)}
.fbody{display:none;padding:0 14px 14px;border-top:1px solid var(--border)}
.finding.open .fbody{display:block}
.fbody p{margin:12px 0;color:var(--muted);font-size:14px}
.diff{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.code{background:var(--code-bg);border-radius:10px;overflow:hidden}
.code .lab{font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.05em;
  padding:7px 12px;color:#aab;border-bottom:1px solid #222833;display:flex;align-items:center;gap:6px}
.code .lab .dot{width:7px;height:7px;border-radius:50%}
pre{margin:0;padding:12px;overflow-x:auto;color:var(--code-text);
  font:12.5px/1.55 ui-monospace,"SF Mono",Menlo,monospace}
.kw{color:var(--kw)} .ty{color:var(--ty)} .st{color:var(--str)} .cm{color:var(--cm);font-style:italic} .at{color:var(--at)}
.factions{display:flex;gap:8px;margin-top:12px;flex-wrap:wrap}
.tag{font-size:12px;color:var(--muted);margin-left:auto;align-self:center}
.empty{text-align:center;color:var(--muted);padding:40px 0}
.toast{position:fixed;bottom:20px;left:50%;transform:translateX(-50%) translateY(80px);
  background:var(--text);color:var(--bg);padding:9px 16px;border-radius:999px;font-size:13px;
  transition:transform .25s;pointer-events:none}
.toast.show{transform:translateX(-50%) translateY(0)}

@media (max-width:640px){
  .summary{grid-template-columns:1fr}
  .stats{grid-template-columns:repeat(2,1fr)}
  .diff{grid-template-columns:1fr}
  header .actions{margin-left:0;width:100%}
  header .actions button{flex:1}
}
