<body>
<div class="wrap">
  <header>
    <div class="logo">⚡︎</div>
    <div>
      <h1>Concurrency Auditor</h1>
      <div class="sub">__SUB__</div>
    </div>
    <div class="actions">
      <button id="themeBtn">Theme</button>
    </div>
  </header>

  <section class="summary">
    <div class="card score">
      <div class="ring">
        <svg width="110" height="110" viewBox="0 0 110 110">
          <circle cx="55" cy="55" r="46" fill="none" stroke="var(--surface-2)" stroke-width="10"/>
          <circle cx="55" cy="55" r="46" fill="none" stroke="var(--accent)" stroke-width="10"
            stroke-linecap="round" stroke-dasharray="289" stroke-dashoffset="__OFFSET__"/>
        </svg>
        <div class="val">__SCORE__%</div>
      </div>
      <div class="lbl">Swift 6 readiness</div>
    </div>
    <div class="card">
      <div class="stats" id="stats"></div>
      <div class="meta">__META__</div>
    </div>
  </section>

  <div class="toolbar" id="chips"></div>
  <div class="toolbar"><input class="search" id="q" placeholder="Search by file, rule, or title…"></div>

  <div id="list"></div>
</div>
<div class="toast" id="toast">Fix copied</div>

<script>
const findings = __FINDINGS__;

const sevs = ["critical","high","medium","low"];
const names = {critical:"Critical",high:"High",medium:"Medium",low:"Low"};
let filter = "all", query = "";

function esc(s){return s.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;")}
function hl(code){
  let s = esc(code);
  const toks = [];
  s = s.replace(/(\/\/[^\n]*)/g, m => { toks.push(`<span class="cm">${m}</span>`); return `\u0000${toks.length-1}\u0000`; });
  s = s.replace(/(@\w+)/g,'<span class="at">$1</span>');
  s = s.replace(/\b(func|var|let|final|class|actor|private|async|await|try|return|if|guard|else|while|for|in|import|deinit|true|nil|self|Task\.detached)\b/g,'<span class="kw">$1</span>');
  s = s.replace(/\b([A-Z][A-Za-z0-9]*)\b(?![^<]*>)/g,'<span class="ty">$1</span>');
  s = s.replace(/\u0000(\d+)\u0000/g,(_,i)=>toks[i]);
  return s;
}

function renderStats(){
  document.getElementById("stats").innerHTML = sevs.map(s=>{
    const n = findings.filter(f=>f.sev===s).length;
    const cls = s==="medium"?"med":s==="critical"?"crit":s;
    return `<div class="stat ${cls}"><div class="n">${n}</div><div class="t">${names[s]}</div></div>`;
  }).join("");
}
function renderChips(){
  const opts = ["all",...sevs];
  document.getElementById("chips").innerHTML = opts.map(o=>{
    const n = o==="all"?findings.length:findings.filter(f=>f.sev===o).length;
    return `<button class="chip ${filter===o?"on":""}" data-f="${o}">${o==="all"?"All":names[o]} · ${n}</button>`;
  }).join("");
  document.querySelectorAll(".chip").forEach(b=>b.onclick=()=>{filter=b.dataset.f;renderChips();renderList();});
}
function renderList(){
  const q = query.toLowerCase();
  const items = findings.filter(f=>(filter==="all"||f.sev===filter) &&
    (!q || (f.title+f.file+f.id).toLowerCase().includes(q)));
  const list = document.getElementById("list");
  if(!items.length){ list.innerHTML = `<div class="empty">No findings match.</div>`; return; }
  list.innerHTML = items.map(f=>`
    <div class="finding">
      <div class="fhead">
        <span class="sev ${f.sev}">${names[f.sev]}</span>
        <div style="min-width:0">
          <div class="ftitle">${esc(f.title)}<span class="rule">${f.id}</span></div>
          <div class="floc">${esc(f.file)}:${f.line}</div>
        </div>
        <svg class="chev" width="16" height="16" viewBox="0 0 16 16"><path d="M6 3l5 5-5 5" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>
      </div>
      <div class="fbody">

        <div class="diff">
          <div class="code"><div class="lab"><span class="dot" style="background:var(--crit)"></span>Flagged code</div><pre>${hl(f.snippet)}</pre></div>
          <div class="code"><div class="lab"><span class="dot" style="background:var(--ok)"></span>How to fix</div><pre>${esc(f.fix)}</pre></div>
        </div>
        <div class="factions">
          <button class="primary" data-copy="${f.file}:${f.line}:${f.id}">Copy fix hint</button>
          <button data-ignore="${f.id}">Ignore rule here</button>
          <span class="tag">${esc(f.why)}</span>
        </div>
      </div>
    </div>`).join("");
  list.querySelectorAll(".fhead").forEach(h=>h.onclick=()=>h.parentElement.classList.toggle("open"));
  list.querySelectorAll("[data-copy]").forEach(b=>b.onclick=e=>{
    e.stopPropagation();
    const f = findings.find(x=>x.file+":"+x.line+":"+x.id===b.dataset.copy);
    try{ navigator.clipboard.writeText(f.fix); }catch(_){}
    toast("Fix copied");
  });
  list.querySelectorAll("[data-ignore]").forEach(b=>b.onclick=()=>toast("Added // audit:ignore " + b.dataset.ignore));
  const first = list.querySelector(".finding"); if(first && filter==="all" && !q) first.classList.add("open");
}
function toast(msg){
  const t=document.getElementById("toast"); t.textContent=msg; t.classList.add("show");
  clearTimeout(t._h); t._h=setTimeout(()=>t.classList.remove("show"),1600);
}
document.getElementById("q").oninput=e=>{query=e.target.value;renderList();};
document.getElementById("themeBtn").onclick=()=>{
  const r=document.documentElement;
  const dark = r.dataset.theme ? r.dataset.theme==="dark" : matchMedia("(prefers-color-scheme: dark)").matches;
  r.dataset.theme = dark ? "light" : "dark";
};
renderStats(); renderChips(); renderList();
</script>
</body>
</html>
